-- Blood moon 3.4 [cerus custom] — base64 + base83 (chunked)
local function base83_decode_chunk(s)
    local chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz!#$%&()*+,-./:;<=>?@^_`{|}~"
    local map = {}
    for i = 1, #chars do map[chars:sub(i,i)] = i-1 end
    local num = 0
    for i = 1, #s do
        num = num * 83 + (map[s:sub(i,i)] or 0)
    end
    local bytes = {}
    while num > 0 do
        table.insert(bytes, 1, num % 256)
        num = math.floor(num / 256)
    end
    return string.char(table.unpack(bytes))
end

local function base83_decode(s)
    local parts = {}
    for part in s:gmatch("[^|]+") do
        table.insert(parts, base83_decode_chunk(part))
    end
    return table.concat(parts)
end

